import React, { useState, useEffect } from 'react';
import './Services.css';

export default function BirthdayService() {
  const [nameInput, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [request, setRequest] = useState('');
  const [options, setOptions] = useState({
    decor: false,
    photo: false,
    music: false,
    fullPackage: false
  });

  const handleSubmit = async (e) => {
    e.preventDefault();

    const optionList = [];
    if (options.decor) optionList.push("Trang trí theo chủ đề");
    if (options.photo) optionList.push("Chụp ảnh – quay video");
    if (options.music) optionList.push("Hoạt náo viên & ban nhạc");
    if (options.fullPackage) optionList.push("Gói trọn gói");

    const body = {
      name: nameInput,
      phone,
      email,
      serviceType: "Sinh nhật",
      request: request + "\nTuỳ chọn thêm: " + (optionList.join(", ") || "Không có")
    };

    try {
      const res = await fetch("http://localhost:5000/api/requests", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body)
      });

      if (res.ok) {
        alert("Đã gửi yêu cầu tư vấn thành công!");
        setName(''); setPhone(''); setEmail(''); setRequest('');
        setOptions({ decor: false, photo: false, music: false, fullPackage: false });
      } else {
        const err = await res.json();
        alert("Gửi thất bại: " + (err.message || JSON.stringify(err)));
      }
    } catch (err) {
      console.error(err);
      alert("Lỗi kết nối server.");
    }
  };

  return (
    <div className="service-detail">
      <div className="banner">
        <div className="overlay">
          <h1>Sinh Nhật Sáng Tạo</h1>
        </div>
      </div>

      <div className="container py-5">
        <div className="row align-items-center">
          <div className="col-md-6 mb-4">
            <img
              src="https://m.media-amazon.com/images/I/816J2DRvTXL._AC_SL1500_.jpg"
              alt="Sinh Nhật Sáng Tạo"
              className="img-fluid rounded shadow"
            />
          </div>
          <div className="col-md-6">
            <h3 className="mb-3 text-danger fw-bold">Tư vấn dịch vụ sự kiện công ty</h3>
            <ul>
            <li>Hội nghị, Gala dinner, Team building</li>
              <li>Trang trí backdrop, sân khấu</li>
              <li>Âm thanh, ánh sáng chuyên nghiệp</li>
              <li>Gói linh hoạt theo ngân sách</li>
            </ul>

            <h5 className="mt-4 mb-2">Tuỳ chọn gói dịch vụ:</h5>
            <form>
              {[
                { id: 'mc', label: 'MC dẫn chương trình' },
                { id: 'photo', label: 'Chụp ảnh – quay video' },
                { id: 'music', label: 'DJ & ban nhạc' },
                { id: 'cake', label: 'Bánh kem theo chủ đề' },
                { id: 'drink', label: 'Đồ uống/Cocktail đặc biệt' },
              ].map(opt => (
                <div className="form-check" key={opt.id}>
                  <input className="form-check-input" type="checkbox" id={opt.id}
                    checked={options[opt.id]}
                    onChange={() => setOptions({ ...options, [opt.id]: !options[opt.id] })} />
                  <label className="form-check-label" htmlFor={opt.id}>{opt.label}</label>
                </div>
              ))}
            </form>
          </div>
        </div>
      </div>

      <div className="booking-form py-5">
        <div className="container">
          <div className="bg-white p-4 rounded shadow">
            <h4 className="mb-3 text-center text-primary">Đặt lịch tư vấn ngay</h4>
            <form onSubmit={handleSubmit}>
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label>Họ và tên</label>
                  <input type="text" className="form-control" value={nameInput} onChange={(e) => setName(e.target.value)} required />
                </div>
                <div className="col-md-6 mb-3">
                  <label>Số điện thoại</label>
                  <input type="tel" className="form-control" value={phone} onChange={(e) => setPhone(e.target.value)} />
                </div>
                <div className="col-md-6 mb-3">
                  <label>Email</label>
                  <input type="email" className="form-control" value={email} onChange={(e) => setEmail(e.target.value)} required />
                </div>
                <div className="col-md-12 mb-3">
                  <label>Nội dung cần tư vấn</label>
                  <textarea className="form-control" rows="4" value={request} onChange={(e) => setRequest(e.target.value)} required />
                </div>
              </div>
              <div className="text-center">
                <button type="submit" className="btn btn-primary px-4">Đặt ngay</button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}
